{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print captured but free to rotate

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.3;        // Horizontal clearance between parts
clearance_z = 0.2;         // Vertical clearance for bridging layers

// Gear parameters
module_size = 2;           // Gear module (tooth size)
pressure_angle = 20;       // Standard pressure angle
gear_height = 10;          // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;           // 12 + 2*9 = 30 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (module_size * sun_teeth) / 2;
planet_pitch_r = (module_size * planet_teeth) / 2;
ring_pitch_r = (module_size * ring_teeth) / 2;

// Planet orbit radius (center of sun to center of planet)
orbit_r = sun_pitch_r + planet_pitch_r;

// Overall dimensions
ring_outer_r = ring_pitch_r + module_size * 1.5;
ring_wall = 3;
total_outer_r = ring_outer_r + ring_wall;

// Carrier dimensions
carrier_thickness = 4;
carrier_hub_r = sun_pitch_r - module_size - clearance_xy;
planet_pin_r = planet_pitch_r - module_size * 1.2;

// Total height
base_height = 3;
total_height = base_height + carrier_thickness + clearance_z + gear_height + clearance_z + carrier_thickness + base_height;

// Z positions
z_lower_carrier = base_height;
z_gears = base_height + carrier_thickness + clearance_z;
z_upper_carrier = z_gears + gear_height + clearance_z;

// === INVOLUTE GEAR MODULES ===

// 2D involute gear profile
module gear_2d(teeth, mod=module_size, pa=pressure_angle) {
    pitch_r = mod * teeth / 2;
    base_r = pitch_r * cos(pa);
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;

    tooth_angle = 360 / teeth;

    // Simplified gear tooth profile using polygon approximation
    difference() {
        circle(r=outer_r, $fn=teeth*8);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle + tooth_angle/4])
            translate([0, 0, 0])
            polygon([
                [root_r * 0.5, 0],
                [outer_r * 1.1, tan(tooth_angle/4) * outer_r * 1.1],
                [outer_r * 1.1, outer_r * 0.5],
                [root_r * 0.5, outer_r * 0.5]
            ]);
        }
    }
}

// Simple but effective gear tooth profile
module gear_profile(teeth, mod=module_size, pa=pressure_angle) {
    pitch_r = mod * teeth / 2;
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;
    base_r = pitch_r * cos(pa);

    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r, $fn=60);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            gear_tooth(pitch_r, base_r, outer_r, root_r, tooth_angle);
        }
    }
}

module gear_tooth(pitch_r, base_r, outer_r, root_r, tooth_angle) {
    // Tooth thickness at pitch circle (standard)
    tooth_thick_angle = tooth_angle / 4;

    // Create tooth profile points
    steps = 8;

    // Involute points
    function involute_point(base_r, angle) = 
        let(r = base_r / cos(angle))
        [r * cos(angle + degrees_roll(base_r, angle)), 
         r * sin(angle + degrees_roll(base_r, angle))];

    function degrees_roll(base_r, angle) = 
        (tan(angle) - angle * PI / 180) * 180 / PI;

    // Simplified tooth using trapezoid approximation
    hull() {
        // Root
        rotate([0, 0, -tooth_thick_angle * 0.7])
        translate([root_r, 0, 0])
        circle(r=0.3, $fn=12);

        rotate([0, 0, tooth_thick_angle * 0.7])
        translate([root_r, 0, 0])
        circle(r=0.3, $fn=12);

        // Tip
        rotate([0, 0, -tooth_thick_angle * 0.4])
        translate([outer_r - 0.2, 0, 0])
        circle(r=0.2, $fn=12);

        rotate([0, 0, tooth_thick_angle * 0.4])
        translate([outer_r - 0.2, 0, 0])
        circle(r=0.2, $fn=12);
    }
}

// External gear (sun and planets)
module external_gear(teeth, height, mod=module_size) {
    pitch_r = mod * teeth / 2;
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;
    tooth_angle = 360 / teeth;

    linear_extrude(height=height, convexity=10)
    union() {
        circle(r=root_r, $fn=60);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            hull() {
                rotate([0, 0, -tooth_angle/8])
                translate([root_r - 0.1, 0])
                circle(r=0.2, $fn=8);

                rotate([0, 0, tooth_angle/8])
                translate([root_r - 0.1, 0])
                circle(r=0.2, $fn=8);

                rotate([0, 0, -tooth_angle/12])
                translate([outer_r - 0.1, 0])
                circle(r=0.15, $fn=8);

                rotate([0, 0, tooth_angle/12])
                translate([outer_r - 0.1, 0])
                circle(r=0.15, $fn=8);
            }
        }
    }
}

// Internal gear (ring gear) - teeth point inward
module internal_gear(teeth, height, outer_r, mod=module_size) {
    pitch_r = mod * teeth / 2;
    inner_r = pitch_r + mod * 1.25;  // Root of internal gear (larger)
    tip_r = pitch_r - mod;           // Tip of internal gear (smaller)
    tooth_angle = 360 / teeth;

    linear_extrude(height=height, convexity=10)
    difference() {
        circle(r=outer_r, $fn=120);

        // Remove center with teeth
        union() {
            circle(r=inner_r, $fn=120);
            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                hull() {
                    rotate([0, 0, -tooth_angle/8])
                    translate([inner_r + 0.1, 0])
                    circle(r=0.2, $fn=8);

                    rotate([0, 0, tooth_angle/8])
                    translate([inner_r + 0.1, 0])
                    circle(r=0.2, $fn=8);

                    rotate([0, 0, -tooth_angle/12])
                    translate([tip_r + 0.1, 0])
                    circle(r=0.15, $fn=8);

                    rotate([0, 0, tooth_angle/12])
                    translate([tip_r + 0.1, 0])
                    circle(r=0.15, $fn=8);
                }
            }
        }
    }
}

// === COMPONENT MODULES ===

// Sun gear with center shaft
module sun_gear() {
    shaft_r = 4;
    shaft_height = total_height + 2;

    color("gold")
    union() {
        // Main gear
        translate([0, 0, z_gears])
        external_gear(sun_teeth, gear_height);

        // Center shaft (extends full height for handle)
        cylinder(r=shaft_r, h=shaft_height, $fn=6);  // Hex for grip
    }
}

// Planet gear with bore for carrier pin
module planet_gear(angle) {
    bore_r = planet_pin_r + clearance_xy;

    color("silver")
    rotate([0, 0, angle])
    translate([orbit_r, 0, z_gears])
    difference() {
        external_gear(planet_teeth, gear_height);

        // Bore for carrier pin
        translate([0, 0, -0.1])
        cylinder(r=bore_r, h=gear_height + 0.2, $fn=30);
    }
}

// Planet carrier (two plates connected by pins through planets)
module carrier() {
    plate_outer_r = orbit_r + planet_pin_r + 3;
    center_bore_r = sun_pitch_r + module_size + clearance_xy;

    color("lightblue")
    union() {
        // Lower carrier plate
        translate([0, 0, z_lower_carrier])
        difference() {
            // Main plate
            cylinder(r=plate_outer_r, h=carrier_thickness, $fn=60);

            // Center bore for sun shaft
            translate([0, 0, -0.1])
            cylinder(r=center_bore_r, h=carrier_thickness + 0.2, $fn=60);

            // Weight reduction holes
            for(i = [0:num_planets-1]) {
                rotate([0, 0, i * 360/num_planets + 60])
                translate([orbit_r, 0, -0.1])
                cylinder(r=planet_pin_r - 1, h=carrier_thickness + 0.2, $fn=30);
            }
        }

        // Planet pins (connect through planet gears)
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets])
            translate([orbit_r, 0, z_lower_carrier])
            cylinder(r=planet_pin_r, h=carrier_thickness + clearance_z + gear_height + clearance_z + carrier_thickness, $fn=30);
        }

        // Upper carrier plate
        translate([0, 0, z_upper_carrier])
        difference() {
            // Main plate
            cylinder(r=plate_outer_r, h=carrier_thickness, $fn=60);

            // Center bore for sun shaft
            translate([0, 0, -0.1])
            cylinder(r=center_bore_r, h=carrier_thickness + 0.2, $fn=60);

            // Planet pin holes (pins are integral, but add relief)
            // Actually pins go through, so no holes needed
        }
    }
}

// Ring gear housing
module ring_gear_housing() {
    floor_h = base_height;
    wall_h = total_height;
    inner_wall_r = ring_outer_r + clearance_xy;
    carrier_clearance_r = orbit_r + planet_pin_r + 3 + clearance_xy;

    color("lightgreen")
    difference() {
        // Outer shell
        cylinder(r=total_outer_r, h=wall_h, $fn=120);

        // Internal gear cavity (gear teeth)
        translate([0, 0, z_gears])
        internal_gear_cavity(ring_teeth, gear_height);

        // Lower carrier cavity
        translate([0, 0, z_lower_carrier - 0.05])
        cylinder(r=carrier_clearance_r, h=carrier_thickness + 0.1, $fn=60);

        // Upper carrier cavity  
        translate([0, 0, z_upper_carrier - 0.05])
        cylinder(r=carrier_clearance_r, h=carrier_thickness + floor_h + 0.2, $fn=60);

        // Sun shaft exit hole (top)
        translate([0, 0, wall_h - floor_h - 0.1])
        cylinder(r=5 + clearance_xy, h=floor_h + 0.2, $fn=30);

        // Sun shaft exit hole (bottom)
        translate([0, 0, -0.1])
        cylinder(r=5 + clearance_xy, h=floor_h + 0.2, $fn=30);
    }
}

// Helper for internal gear cavity
module internal_gear_cavity(teeth, height) {
    mod = module_size;
    pitch_r = mod * teeth / 2;
    inner_r = pitch_r + mod * 1.25 + clearance_xy;
    tip_r = pitch_r - mod;
    tooth_angle = 360 / teeth;

    linear_extrude(height=height, convexity=10)
    union() {
        circle(r=inner_r, $fn=120);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            hull() {
                rotate([0, 0, -tooth_angle/8])
                translate([inner_r + 0.1, 0])
                circle(r=0.2, $fn=8);

                rotate([0, 0, tooth_angle/8])
                translate([inner_r + 0.1, 0])
                circle(r=0.2, $fn=8);

                rotate([0, 0, -tooth_angle/12])
                translate([tip_r - clearance_xy, 0])
                circle(r=0.15, $fn=8);

                rotate([0, 0, tooth_angle/12])
                translate([tip_r - clearance_xy, 0])
                circle(r=0.15, $fn=8);
            }
        }
    }
}

// === ASSEMBLY ===

module planetary_gearbox() {
    // Ring gear housing (stationary)
    ring_gear_housing();

    // Sun gear (input)
    sun_gear();

    // Planet gears
    for(i = [0:num_planets-1]) {
        planet_gear(i * 360/num_planets);
    }

    // Carrier (output)
    carrier();
}

// Render the complete assembly
planetary_gearbox();

// Display key dimensions for verification
echo("=== PLANETARY GEARBOX DIMENSIONS ===");
echo(str("Sun teeth: ", sun_teeth, " Pitch R: ", sun_pitch_r));
echo(str("Planet teeth: ", planet_teeth, " Pitch R: ", planet_pitch_r));
echo(str("Ring teeth: ", ring_teeth, " Pitch R: ", ring_pitch_r));
echo(str("Orbit radius: ", orbit_r));
echo(str("Total outer radius: ", total_outer_r));
echo(str("Total height: ", total_height));
echo(str("XY Clearance: ", clearance_xy, "mm"));
echo(str("Z Clearance: ", clearance_z, "mm"));'}

{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print captured but free to rotate

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.35;       // Horizontal clearance between parts
clearance_z = 0.25;        // Vertical clearance for bridging layers

// Gear parameters
mod = 2.0;                 // Gear module (tooth size)
pressure_angle = 20;       // Standard pressure angle
gear_height = 12;          // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;           // 12 + 2*9 = 30 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (mod * sun_teeth) / 2;
planet_pitch_r = (mod * planet_teeth) / 2;
ring_pitch_r = (mod * ring_teeth) / 2;

sun_outer_r = sun_pitch_r + mod;
planet_outer_r = planet_pitch_r + mod;
ring_inner_r = ring_pitch_r - mod;  // Inner tip of ring teeth

// Planet orbit radius (center of sun to center of planet)
orbit_r = sun_pitch_r + planet_pitch_r;

// Overall dimensions
ring_base_r = ring_pitch_r + mod * 1.5;
housing_wall = 4;
housing_outer_r = ring_base_r + housing_wall;

// Carrier dimensions  
carrier_plate_thickness = 5;
carrier_outer_r = orbit_r + planet_outer_r + 2;
carrier_hub_clearance = sun_outer_r + clearance_xy + 1;
planet_pin_r = (planet_pitch_r - mod * 1.25) - clearance_xy - 1;  // Smaller than planet bore

// Height layout
base_thickness = 4;
z_base = 0;
z_lower_carrier = base_thickness;
z_gears = z_lower_carrier + carrier_plate_thickness + clearance_z;
z_upper_carrier = z_gears + gear_height + clearance_z;
z_top = z_upper_carrier + carrier_plate_thickness + base_thickness;

total_height = z_top;

// === QUALITY SETTINGS ===
$fn = 60;

// === INVOLUTE GEAR FUNCTIONS ===

// Calculate involute point at given angle
function involute_intersect_angle(base_r, r) = 
    sqrt(pow(r/base_r, 2) - 1) * 180 / PI;

function involute_point(base_r, angle) = 
    let(r = base_r / cos(angle))
    let(roll = tan(angle) * 180 / PI - angle)
    [r * cos(roll), r * sin(roll)];

// Generate gear tooth profile points
function gear_tooth_points(pitch_r, base_r, root_r, outer_r, steps=6) =
    let(
        // Angles
        pitch_angle = involute_intersect_angle(base_r, pitch_r),
        outer_angle = involute_intersect_angle(base_r, min(outer_r, base_r * 1.6)),
        tooth_half_thick = 90 / len([for(i=[0:steps]) i]) * PI / (2 * pitch_r) * pitch_r,  // Approximate

        // Generate involute curve points
        inv_points = [for(i=[0:steps]) 
            let(angle = i * outer_angle / steps)
            involute_point(base_r, angle)
        ]
    )
    inv_points;

// === GEAR MODULES ===

// Simple trapezoidal gear tooth (reliable for printing)
module gear_tooth_2d(pitch_r, mod) {
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;

    // Tooth thickness at pitch circle
    tooth_thick = mod * PI / 2 * 0.48;  // Slightly less than theoretical for clearance

    // Angles
    pitch_half_angle = asin(tooth_thick / (2 * pitch_r));
    tip_half_angle = pitch_half_angle * 0.65;  // Narrower at tip
    root_half_angle = pitch_half_angle * 1.1;  // Wider at root

    polygon([
        [root_r * cos(root_half_angle), root_r * sin(root_half_angle)],
        [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
        [outer_r * cos(tip_half_angle), -outer_r * sin(tip_half_angle)],
        [root_r * cos(root_half_angle), -root_r * sin(root_half_angle)]
    ]);
}

// External gear (sun and planets)
module external_gear_2d(teeth, mod) {
    pitch_r = mod * teeth / 2;
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;
    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r, $fn=teeth*6);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            gear_tooth_2d(pitch_r, mod);
        }
    }
}

// Internal gear tooth (points inward)
module internal_gear_tooth_2d(pitch_r, mod) {
    outer_r = pitch_r + mod * 1.25;  // Root of internal gear
    inner_r = pitch_r - mod;          // Tip of internal gear

    // Tooth thickness
    tooth_thick = mod * PI / 2 * 0.52;  // Slightly more for internal

    // Angles
    pitch_half_angle = asin(tooth_thick / (2 * pitch_r));
    tip_half_angle = pitch_half_angle * 1.1;
    root_half_angle = pitch_half_angle * 0.7;

    polygon([
        [outer_r * cos(root_half_angle), outer_r * sin(root_half_angle)],
        [inner_r * cos(tip_half_angle), inner_r * sin(tip_half_angle)],
        [inner_r * cos(tip_half_angle), -inner_r * sin(tip_half_angle)],
        [outer_r * cos(root_half_angle), -outer_r * sin(root_half_angle)]
    ]);
}

// Internal gear profile (ring gear)
module internal_gear_2d(teeth, mod, outer_r) {
    pitch_r = mod * teeth / 2;
    root_r = pitch_r + mod * 1.25;  // Internal gear root is larger
    tooth_angle = 360 / teeth;

    difference() {
        circle(r=outer_r, $fn=120);

        union() {
            circle(r=root_r, $fn=teeth*6);
            for(i = [0:teeth-1]) {
                rotate([0, 0, i * tooth_angle])
                internal_gear_tooth_2d(pitch_r, mod);
            }
        }
    }
}

// === MAIN COMPONENTS ===

// Sun gear with hex shaft
module sun_gear() {
    shaft_r = 5;

    color("Gold")
    union() {
        // Gear body
        translate([0, 0, z_gears])
        linear_extrude(height=gear_height, convexity=10)
        external_gear_2d(sun_teeth, mod);

        // Lower shaft (hex for grip)
        cylinder(r=shaft_r, h=z_gears + gear_height/2, $fn=6);

        // Upper shaft  
        translate([0, 0, z_gears + gear_height/2])
        cylinder(r=shaft_r, h=total_height - z_gears - gear_height/2 + 5, $fn=6);
    }
}

// Planet gear
module planet_gear(angle_offset) {
    planet_bore_r = planet_pin_r + clearance_xy;

    color("Silver")
    rotate([0, 0, angle_offset])
    translate([orbit_r, 0, z_gears])
    difference() {
        linear_extrude(height=gear_height, convexity=10)
        external_gear_2d(planet_teeth, mod);

        // Bore for carrier pin
        translate([0, 0, -0.1])
        cylinder(r=planet_bore_r, h=gear_height + 0.2, $fn=40);
    }
}

// Carrier assembly (two plates connected by planet pins)
module carrier() {
    sun_bore_r = sun_outer_r + clearance_xy + 0.5;
    plate_outer_r = carrier_outer_r;

    color("SteelBlue")
    difference() {
        union() {
            // Lower carrier plate
            translate([0, 0, z_lower_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);

            // Planet pins extending through gears
            for(i = [0:num_planets-1]) {
                rotate([0, 0, i * 360/num_planets])
                translate([orbit_r, 0, z_lower_carrier])
                cylinder(r=planet_pin_r, h=carrier_plate_thickness + clearance_z + gear_height + clearance_z + carrier_plate_thickness, $fn=40);
            }

            // Upper carrier plate
            translate([0, 0, z_upper_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);
        }

        // Central bore for sun gear shaft (through both plates)
        translate([0, 0, z_lower_carrier - 0.1])
        cylinder(r=sun_bore_r, h=z_upper_carrier + carrier_plate_thickness - z_lower_carrier + 0.2, $fn=60);

        // Lightening holes in lower plate
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.6, 0, z_lower_carrier - 0.1])
            cylinder(r=4, h=carrier_plate_thickness + 0.2, $fn=30);
        }

        // Lightening holes in upper plate
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.6, 0, z_upper_carrier - 0.1])
            cylinder(r=4, h=carrier_plate_thickness + 0.2, $fn=30);
        }
    }
}

// Ring gear and housing
module ring_housing() {
    carrier_cavity_r = carrier_outer_r + clearance_xy;
    sun_shaft_hole_r = 6 + clearance_xy;

    color("LimeGreen", 0.8)
    difference() {
        // Outer housing cylinder
        cylinder(r=housing_outer_r, h=total_height, $fn=100);

        // Ring gear teeth cavity
        translate([0, 0, z_gears - 0.1])
        linear_extrude(height=gear_height + 0.2, convexity=10)
        difference() {
            circle(r=ring_base_r + 1, $fn=100);
            difference() {
                circle(r=ring_pitch_r + mod * 1.25 + clearance_xy, $fn=ring_teeth*6);
                for(i = [0:ring_teeth-1]) {
                    rotate([0, 0, i * 360/ring_teeth])
                    internal_gear_tooth_2d(ring_pitch_r, mod);
                }
            }
        }

        // Lower carrier cavity
        translate([0, 0, z_lower_carrier - 0.05])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + 0.1, $fn=80);

        // Upper carrier cavity (extends through top)
        translate([0, 0, z_upper_carrier - 0.05])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + base_thickness + 0.2, $fn=80);

        // Sun shaft hole - bottom
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_hole_r, h=base_thickness + 0.2, $fn=40);

        // Sun shaft hole - top (hex shaped for visual)
        translate([0, 0, total_height - base_thickness - 0.1])
        cylinder(r=sun_shaft_hole_r, h=base_thickness + 0.2, $fn=6);
    }
}

// === ANTI-FUSION BRIDGES ===
// Add small bridges/gaps to prevent parts from fusing during printing

module anti_fusion_features() {
    // Small vertical gaps between carrier plates and housing floor/ceiling
    // These are already handled by clearance_z
}

// === ASSEMBLY ===

module planetary_gearbox() {
    // Housing with ring gear (fixed)
    ring_housing();

    // Sun gear (input - rotates)
    sun_gear();

    // Planet gears (rotate on pins and orbit)
    for(i = [0:num_planets-1]) {
        planet_gear(i * 360/num_planets);
    }

    // Carrier (output - rotates)
    carrier();
}

// === CROSS SECTION VIEW (for debugging) ===
module cross_section() {
    difference() {
        planetary_gearbox();
        translate([0, -100, -1])
        cube([100, 200, 100]);
    }
}

// Render complete assembly
planetary_gearbox();

// Uncomment for cross-section view:
// cross_section();

