{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print captured but free to rotate

// === PARAMETERS ===

// Clearances for print-in-place (PETG with 0.4mm nozzle)
clearance_xy = 0.35;       // Horizontal clearance between parts
clearance_z = 0.3;         // Vertical clearance for bridging layers

// Gear parameters
mod = 2.0;                 // Gear module (tooth size)
pressure_angle = 20;       // Standard pressure angle
gear_height = 12;          // Height of gear teeth

// Tooth counts (must satisfy: ring = sun + 2*planet for proper meshing)
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;           // 12 + 2*9 = 30 ✓

// Number of planet gears
num_planets = 3;

// Derived dimensions
sun_pitch_r = (mod * sun_teeth) / 2;
planet_pitch_r = (mod * planet_teeth) / 2;
ring_pitch_r = (mod * ring_teeth) / 2;

sun_outer_r = sun_pitch_r + mod;
planet_outer_r = planet_pitch_r + mod;
ring_inner_r = ring_pitch_r - mod;  // Inner tip of ring teeth

// Planet orbit radius (center of sun to center of planet)
orbit_r = sun_pitch_r + planet_pitch_r;

// Overall dimensions
ring_base_r = ring_pitch_r + mod * 1.5;
housing_wall = 4;
housing_outer_r = ring_base_r + housing_wall;

// Carrier dimensions  
carrier_plate_thickness = 5;
carrier_outer_r = orbit_r + planet_outer_r + 2;
carrier_hub_clearance = sun_outer_r + clearance_xy + 1;
planet_pin_r = (planet_pitch_r - mod * 1.25) - clearance_xy - 1.5;  // Must be smaller than planet bore

// Height layout
base_thickness = 4;
z_base = 0;
z_lower_carrier = base_thickness;
z_gears = z_lower_carrier + carrier_plate_thickness + clearance_z;
z_upper_carrier = z_gears + gear_height + clearance_z;
z_top = z_upper_carrier + carrier_plate_thickness + base_thickness;

total_height = z_top;

// === QUALITY SETTINGS ===
$fn = 60;

// === GEAR MODULES ===

// Simple trapezoidal gear tooth (reliable for printing)
module gear_tooth_2d(pitch_r, mod) {
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;

    // Tooth thickness at pitch circle
    tooth_thick = mod * PI / 2 * 0.45;  // Leave clearance for meshing

    // Angles
    pitch_half_angle = asin(tooth_thick / (2 * pitch_r));
    tip_half_angle = pitch_half_angle * 0.6;  // Narrower at tip
    root_half_angle = pitch_half_angle * 1.15;  // Wider at root

    polygon([
        [root_r * cos(root_half_angle), root_r * sin(root_half_angle)],
        [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
        [outer_r * cos(tip_half_angle), -outer_r * sin(tip_half_angle)],
        [root_r * cos(root_half_angle), -root_r * sin(root_half_angle)]
    ]);
}

// External gear (sun and planets)
module external_gear_2d(teeth, mod) {
    pitch_r = mod * teeth / 2;
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;
    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r, $fn=teeth*6);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            gear_tooth_2d(pitch_r, mod);
        }
    }
}

// Internal gear tooth (points inward)
module internal_gear_tooth_2d(pitch_r, mod) {
    outer_r = pitch_r + mod * 1.25;  // Root of internal gear
    inner_r = pitch_r - mod;          // Tip of internal gear

    // Tooth thickness - slightly wider for internal gear
    tooth_thick = mod * PI / 2 * 0.55;

    // Angles
    pitch_half_angle = asin(tooth_thick / (2 * pitch_r));
    tip_half_angle = pitch_half_angle * 1.2;
    root_half_angle = pitch_half_angle * 0.65;

    polygon([
        [outer_r * cos(root_half_angle), outer_r * sin(root_half_angle)],
        [inner_r * cos(tip_half_angle), inner_r * sin(tip_half_angle)],
        [inner_r * cos(tip_half_angle), -inner_r * sin(tip_half_angle)],
        [outer_r * cos(root_half_angle), -outer_r * sin(root_half_angle)]
    ]);
}

// === MAIN COMPONENTS ===

// Sun gear with hex shaft
module sun_gear() {
    shaft_r = 5;
    shaft_hex_r = 6;

    color("Gold")
    union() {
        // Gear body
        translate([0, 0, z_gears])
        linear_extrude(height=gear_height, convexity=10)
        external_gear_2d(sun_teeth, mod);

        // Lower shaft (round, sits in housing hole)
        cylinder(r=shaft_r, h=z_gears, $fn=40);

        // Upper shaft extending above for turning
        translate([0, 0, z_gears])
        cylinder(r=shaft_r, h=total_height - z_gears + 8, $fn=6);  // Hex for grip
    }
}

// Planet gear
module planet_gear(angle_offset) {
    planet_bore_r = planet_pin_r + clearance_xy;

    color("Silver")
    rotate([0, 0, angle_offset])
    translate([orbit_r, 0, z_gears])
    difference() {
        linear_extrude(height=gear_height, convexity=10)
        external_gear_2d(planet_teeth, mod);

        // Bore for carrier pin
        translate([0, 0, -0.1])
        cylinder(r=planet_bore_r, h=gear_height + 0.2, $fn=40);
    }
}

// Carrier assembly (two plates connected by planet pins)
module carrier() {
    sun_bore_r = sun_outer_r + clearance_xy + 0.5;
    plate_outer_r = carrier_outer_r;
    pin_total_height = carrier_plate_thickness + clearance_z + gear_height + clearance_z + carrier_plate_thickness;

    color("SteelBlue")
    difference() {
        union() {
            // Lower carrier plate
            translate([0, 0, z_lower_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);

            // Planet pins extending through gears
            for(i = [0:num_planets-1]) {
                rotate([0, 0, i * 360/num_planets])
                translate([orbit_r, 0, z_lower_carrier])
                cylinder(r=planet_pin_r, h=pin_total_height, $fn=40);
            }

            // Upper carrier plate
            translate([0, 0, z_upper_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);
        }

        // Central bore for sun gear shaft (through both plates)
        translate([0, 0, z_lower_carrier - 0.1])
        cylinder(r=sun_bore_r, h=z_upper_carrier + carrier_plate_thickness - z_lower_carrier + 0.2, $fn=60);

        // Lightening holes in lower plate (between planets)
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.55, 0, z_lower_carrier - 0.1])
            cylinder(r=5, h=carrier_plate_thickness + 0.2, $fn=30);
        }

        // Lightening holes in upper plate
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.55, 0, z_upper_carrier - 0.1])
            cylinder(r=5, h=carrier_plate_thickness + 0.2, $fn=30);
        }
    }
}

// Ring gear and housing
module ring_housing() {
    carrier_cavity_r = carrier_outer_r + clearance_xy;
    sun_shaft_hole_r = 5.5 + clearance_xy;
    ring_root_r = ring_pitch_r + mod * 1.25;

    color("LimeGreen", 0.85)
    difference() {
        // Outer housing cylinder
        cylinder(r=housing_outer_r, h=total_height, $fn=100);

        // Ring gear teeth cavity - create internal gear profile
        translate([0, 0, z_gears - 0.05])
        linear_extrude(height=gear_height + 0.1, convexity=10)
        union() {
            // Base circle at root
            circle(r=ring_root_r + clearance_xy, $fn=ring_teeth*6);
            // Add teeth slots
            for(i = [0:ring_teeth-1]) {
                rotate([0, 0, i * 360/ring_teeth])
                internal_gear_tooth_2d(ring_pitch_r, mod);
            }
        }

        // Lower carrier cavity
        translate([0, 0, z_lower_carrier - 0.05])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + clearance_z + 0.1, $fn=80);

        // Upper carrier cavity (extends through top)
        translate([0, 0, z_upper_carrier - clearance_z - 0.05])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + base_thickness + clearance_z + 0.2, $fn=80);

        // Sun shaft hole - bottom
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_hole_r, h=base_thickness + 0.2, $fn=40);

        // Sun shaft hole - top
        translate([0, 0, total_height - base_thickness - 0.1])
        cylinder(r=sun_shaft_hole_r, h=base_thickness + 0.2, $fn=6);

        // Viewing windows in housing wall (optional - helps see mechanism)
        for(i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([housing_outer_r - housing_wall/2, 0, z_gears + gear_height/2])
            rotate([0, 90, 0])
            cylinder(r=4, h=housing_wall + 1, center=true, $fn=30);
        }
    }
}

// === ASSEMBLY ===

module planetary_gearbox() {
    // Housing with ring gear (fixed)
    ring_housing();

    // Sun gear (input - rotates)
    sun_gear();

    // Planet gears (rotate on pins and orbit)
    for(i = [0:num_planets-1]) {
        planet_gear(i * 360/num_planets);
    }

    // Carrier (output - rotates)
    carrier();
}

// === CROSS SECTION VIEW ===
module cross_section() {
    difference() {
        planetary_gearbox();
        translate([0, -100, -1])
        cube([100, 200, 100]);
    }
}

// Toggle between full view and cross-section
show_cross_section = false;

if (show_cross_section) {
    cross_section();
} else {
    planetary_gearbox();
}

// === INFO OUTPUT ===
echo("========================================");
echo("PRINT-IN-PLACE PLANETARY GEARBOX");
echo("========================================");
echo(str("Sun: ", sun_teeth, " teeth, pitch R=", sun_pitch_r, "mm"));
echo(str("Planet: ", planet_teeth, " teeth, pitch R=", planet_pitch_r, "mm"));
echo(str("Ring: ", ring_teeth, " teeth, pitch R=", ring_pitch_r, "mm"));
echo(str("Gear ratio: ", 1 + ring_teeth/sun_teeth, ":1"));
echo(str("Orbit radius: ", orbit_r, "mm"));
echo(str("Housing diameter: ", housing_outer_r * 2, "mm"));
echo(str("Total height: ", total_height, "mm"));
echo("----------------------------------------");
echo(str("XY clearance: ", clearance_xy, "mm"));
echo(str("Z clearance: ", clearance_z, "mm"));
echo(str("Planet pin radius: ", planet_pin_r, "mm"));
echo("========================================");'}

