planet_pin_r = planet_root_r - clearance_xy - 2;  // Must fit inside planet bore with clearance

// Sun shaft dimensions
sun_shaft_r = 5;
sun_shaft_clearance = sun_shaft_r + clearance_xy;

// Height layout
base_thickness = 4;
z_base = 0;
z_lower_carrier = base_thickness;
z_gears = z_lower_carrier + carrier_plate_thickness + clearance_z;
z_upper_carrier = z_gears + gear_height + clearance_z;
z_top = z_upper_carrier + carrier_plate_thickness + base_thickness;

total_height = z_top;

// === QUALITY SETTINGS ===
$fn = 60;

// === GEAR MODULES ===

// Gear tooth profile - trapezoidal approximation of involute
module gear_tooth_2d(pitch_r, mod, backlash=0.1) {
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;

    // Tooth thickness with backlash
    tooth_thick = (mod * PI / 2) - backlash;

    // Calculate angles
    pitch_angle = atan2(tooth_thick/2, pitch_r);
    tip_angle = pitch_angle * 0.55;
    root_angle = pitch_angle * 1.2;

    // Create tooth shape
    polygon([
        [root_r * cos(-root_angle), root_r * sin(-root_angle)],
        [root_r * cos(root_angle), root_r * sin(root_angle)],
        [outer_r * cos(tip_angle), outer_r * sin(tip_angle)],
        [outer_r * cos(-tip_angle), outer_r * sin(-tip_angle)]
    ]);
}

// External gear (sun and planets)
module external_gear_2d(teeth, mod, backlash=0.1) {
    pitch_r = mod * teeth / 2;
    root_r = pitch_r - mod * 1.25;
    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r, $fn=teeth*6);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            gear_tooth_2d(pitch_r, mod, backlash);
        }
    }
