module internal_tooth_cutout_2d(pitch_r, mod, extra_clearance=0) {
    root_r = pitch_r + mod * 1.25;  // Internal gear root (outer)
    tip_r = pitch_r - mod;           // Internal gear tip (inner)

    // Wider tooth space for clearance
    tooth_thick = (mod * PI / 2) + extra_clearance;

    pitch_angle = atan2(tooth_thick/2, pitch_r);
    tip_angle = pitch_angle * 1.3;
    root_angle = pitch_angle * 0.6;

    polygon([
        [root_r * cos(-root_angle), root_r * sin(-root_angle)],
        [root_r * cos(root_angle), root_r * sin(root_angle)],
        [(tip_r - extra_clearance) * cos(tip_angle), (tip_r - extra_clearance) * sin(tip_angle)],
        [(tip_r - extra_clearance) * cos(-tip_angle), (tip_r - extra_clearance) * sin(-tip_angle)]
    ]);
}

// === MAIN COMPONENTS ===

// Sun gear with shaft
module sun_gear() {
    color("Gold")
    union() {
        // Gear body
        translate([0, 0, z_gears])
        linear_extrude(height=gear_height, convexity=10)
        external_gear_2d(sun_teeth, mod, 0.15);

