        translate([0, 0, -0.1])
        cylinder(r=planet_bore_r, h=gear_height + 0.2, $fn=40);
    }
}

// Carrier assembly
module carrier() {
    sun_bore_r = sun_outer_r + clearance_xy + 1;
    plate_outer_r = carrier_outer_r;
    pin_total_height = carrier_plate_thickness + clearance_z + gear_height + clearance_z + carrier_plate_thickness;

    color("SteelBlue")
    difference() {
        union() {
            // Lower carrier plate
            translate([0, 0, z_lower_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);

            // Planet pins
            for(i = [0:num_planets-1]) {
                rotate([0, 0, i * 360/num_planets])
                translate([orbit_r, 0, z_lower_carrier])
                cylinder(r=planet_pin_r, h=pin_total_height, $fn=40);
            }

            // Upper carrier plate
            translate([0, 0, z_upper_carrier])
            cylinder(r=plate_outer_r, h=carrier_plate_thickness, $fn=80);
        }

        // Central bore for sun gear
        translate([0, 0, z_lower_carrier - 0.1])
        cylinder(r=sun_bore_r, h=pin_total_height + 0.2, $fn=60);

        // Lightening/viewing holes
        for(i = [0:num_planets-1]) {
            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.5, 0, z_lower_carrier - 0.1])
            cylinder(r=4, h=carrier_plate_thickness + 0.2, $fn=24);

            rotate([0, 0, i * 360/num_planets + 60])
            translate([orbit_r * 0.5, 0, z_upper_carrier - 0.1])
            cylinder(r=4, h=carrier_plate_thickness + 0.2, $fn=24);
        }
    }
}

// Ring gear housing
module ring_housing() {
    carrier_cavity_r = carrier_outer_r + clearance_xy;
    ring_root_r = ring_pitch_r + mod * 1.25;

    color("LimeGreen", 0.9)
    difference() {
        // Outer housing
        cylinder(r=housing_outer_r, h=total_height, $fn=120);

        // Ring gear internal teeth
        translate([0, 0, z_gears - 0.05])
        linear_extrude(height=gear_height + 0.1, convexity=10)
        union() {
            // Root circle
            circle(r=ring_root_r + clearance_xy, $fn=ring_teeth*6);
            // Tooth spaces
            for(i = [0:ring_teeth-1]) {
                rotate([0, 0, i * 360/ring_teeth])
                internal_tooth_cutout_2d(ring_pitch_r, mod, clearance_xy);
            }
        }

        // Lower carrier cavity (must bridge over this)
        translate([0, 0, z_lower_carrier - 0.1])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + clearance_z + 0.15, $fn=80);

        // Upper carrier cavity
        translate([0, 0, z_upper_carrier - clearance_z - 0.1])
        cylinder(r=carrier_cavity_r, h=carrier_plate_thickness + base_thickness + clearance_z + 0.2, $fn=80);

        // Sun shaft holes
        translate([0, 0, -0.1])
        cylinder(r=sun_shaft_clearance, h=base_thickness + 0.2, $fn=40);

        translate([0, 0, total_height - base_thickness - 0.1])
        cylinder(r=sun_shaft_clearance + 1, h=base_thickness + 0.2, $fn=6);

        // Side viewing windows
        for(i = [0:2]) {
            rotate([0, 0, i * 120 + 60])
            translate([housing_outer_r, 0, z_gears + gear_height/2])
            rotate([0, 90, 0])
            cylinder(r=5, h=housing_wall*2, center=true, $fn=30);
        }
    }
}

// Retention features - thin bridges that print but break easily
module retention_tabs() {
    // Small tabs at z_gears level to help parts stay in place during printing
    // These will break free when mechanism is first operated
}

// === ASSEMBLY ===

module planetary_gearbox() {
    ring_housing();
    sun_gear();
    for(i = [0:num_planets-1]) {
        planet_gear(i * 360/num_planets);
    }
    carrier();
}

// === VISUALIZATION ===

// Cross section for verification
module cross_section() {
    difference() {
        planetary_gearbox();
        translate([0, -100, -1])
        cube([100, 200, 100]);
    }
}

// Choose view
view_mode = "full";  // "full" or "cross"

if (view_mode == "cross") {
    cross_section();
} else {
    planetary_gearbox();
}

// === PRINT INFO ===
echo("==========================================");
echo("  PRINT-IN-PLACE PLANETARY GEARBOX");
echo("==========================================");
echo(str("Outer diameter: ", housing_outer_r * 2, " mm"));
echo(str("Total height: ", total_height, " mm"));
echo(str("Gear ratio: ", 1 + ring_teeth/sun_teeth, ":1"));
echo("------------------------------------------");
echo(str("XY clearance: ", clearance_xy, " mm"));
echo(str("Z clearance: ", clearance_z, " mm"));
echo("------------------------------------------");
echo("Print settings: PETG, 0.4mm nozzle, 0.1mm layers");
echo("Print orientation: Z-up (gear axis vertical)");
