{'content': '// Print-in-Place Planetary Gearbox
// Designed for PETG, 0.4mm nozzle, 0.1mm layer height
// All parts print captured but free to rotate immediately after printing

// === PRINT-IN-PLACE DESIGN PHILOSOPHY ===
// 1. All clearances sized for PETG with 0.4mm nozzle
// 2. Vertical gaps use bridging-friendly dimensions
// 3. No overhangs exceed 45 degrees
// 4. All moving parts captured but free to rotate

// === PARAMETERS ===

// Clearances - Critical for print-in-place success
clearance_xy = 0.4;        // Horizontal gap between moving parts
clearance_z = 0.35;        // Vertical gap for bridging (3-4 layers at 0.1mm)

// Gear module and dimensions
mod = 2.0;                 // Gear module (mm per tooth on pitch circle)
gear_height = 12;          // Height of gear teeth section

// Tooth counts - Must satisfy: ring_teeth = sun_teeth + 2 * planet_teeth
sun_teeth = 12;
planet_teeth = 9;
ring_teeth = 30;           // 12 + 2*9 = 30 ✓

num_planets = 3;

// Calculated gear geometry
sun_pitch_r = (mod * sun_teeth) / 2;        // 12mm
planet_pitch_r = (mod * planet_teeth) / 2;  // 9mm  
ring_pitch_r = (mod * ring_teeth) / 2;      // 30mm

sun_outer_r = sun_pitch_r + mod;            // 14mm
planet_outer_r = planet_pitch_r + mod;      // 11mm
planet_root_r = planet_pitch_r - mod * 1.25; // 6.5mm

orbit_r = sun_pitch_r + planet_pitch_r;     // 21mm (center-to-center)

// Housing dimensions
ring_root_r = ring_pitch_r + mod * 1.25;    // 32.5mm
housing_wall = 4;
housing_outer_r = ring_root_r + housing_wall; // 36.5mm

// Carrier dimensions
carrier_plate_thickness = 5;
carrier_outer_r = orbit_r + planet_outer_r + 2;  // 34mm
planet_pin_r = planet_root_r - clearance_xy - 1.5;  // ~4.6mm

// Sun shaft
sun_shaft_r = 5;

// Vertical layout (bottom to top)
base_thickness = 4;
z_lower_carrier = base_thickness;                           // 4mm
z_gears = z_lower_carrier + carrier_plate_thickness + clearance_z;  // 9.35mm
z_upper_carrier = z_gears + gear_height + clearance_z;      // 21.7mm
z_top = z_upper_carrier + carrier_plate_thickness + base_thickness; // 30.7mm

total_height = z_top;

// Quality
$fn = 80;

// === GEAR TOOTH MODULES ===

// Simplified involute-like tooth for external gears
module external_tooth_2d(pitch_r, mod) {
    outer_r = pitch_r + mod;
    root_r = pitch_r - mod * 1.25;

    // Tooth thickness at pitch circle (with backlash)
    circular_pitch = mod * PI;
    tooth_thick = circular_pitch / 2 - 0.2;  // Subtract backlash

    // Angular positions
    pitch_half_angle = asin((tooth_thick/2) / pitch_r);
    tip_half_angle = pitch_half_angle * 0.5;  // Narrower at tip
    root_half_angle = pitch_half_angle * 1.3; // Wider at root for strength

    polygon([
        [root_r * cos(root_half_angle), root_r * sin(root_half_angle)],
        [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
        [outer_r * cos(-tip_half_angle), outer_r * sin(-tip_half_angle)],
        [root_r * cos(-root_half_angle), root_r * sin(-root_half_angle)]
    ]);
}

// External gear profile (sun, planets)
module external_gear_2d(teeth, mod) {
    pitch_r = mod * teeth / 2;
    root_r = pitch_r - mod * 1.25;
    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r, $fn=teeth*6);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            external_tooth_2d(pitch_r, mod);
        }
    }
}

// Internal gear tooth space (cut into ring)
module internal_tooth_space_2d(pitch_r, mod, clearance=0) {
    root_r = pitch_r + mod * 1.25;  // Root is outer for internal gear
    tip_r = pitch_r - mod;           // Tip is inner

    circular_pitch = mod * PI;
    space_width = circular_pitch / 2 + 0.2 + clearance;  // Wider space for clearance

    pitch_half_angle = asin((space_width/2) / pitch_r);
    tip_half_angle = pitch_half_angle * 1.4;
    root_half_angle = pitch_half_angle * 0.6;

    polygon([
        [root_r * cos(root_half_angle), root_r * sin(root_half_angle)],
        [(tip_r - clearance) * cos(tip_half_angle), (tip_r - clearance) * sin(tip_half_angle)],
        [(tip_r - clearance) * cos(-tip_half_angle), (tip_r - clearance) * sin(-tip_half_angle)],
        [root_r * cos(-root_half_angle), root_r * sin(-root_half_angle)]
    ]);
}

// Internal gear cavity profile
module internal_gear_cavity_2d(teeth, mod, clearance) {
    pitch_r = mod * teeth / 2;
    root_r = pitch_r + mod * 1.25;
    tooth_angle = 360 / teeth;

    union() {
        circle(r=root_r + clearance, $fn=teeth*6);
        for(i = [0:teeth-1]) {
            rotate([0, 0, i * tooth_angle])
            internal_tooth_space_2d(pitch_r, mod, clearance);
