planet_outer_r = planet_pitch_r + mod;      // 11mm
planet_root_r = planet_pitch_r - mod * 1.25; // 6.5mm

orbit_r = sun_pitch_r + planet_pitch_r;     // 21mm (center-to-center)

// Housing dimensions
ring_root_r = ring_pitch_r + mod * 1.25;    // 32.5mm
housing_wall = 4;
housing_outer_r = ring_root_r + housing_wall; // 36.5mm

// Carrier dimensions
carrier_plate_thickness = 5;
carrier_outer_r = orbit_r + planet_outer_r + 2;  // 34mm
planet_pin_r = planet_root_r - clearance_xy - 1.5;  // ~4.6mm

// Sun shaft
sun_shaft_r = 5;

