    // Tooth thickness at pitch circle (with backlash)
    circular_pitch = mod * PI;
    tooth_thick = circular_pitch / 2 - 0.2;  // Subtract backlash

    // Angular positions
    pitch_half_angle = asin((tooth_thick/2) / pitch_r);
    tip_half_angle = pitch_half_angle * 0.5;  // Narrower at tip
    root_half_angle = pitch_half_angle * 1.3; // Wider at root for strength

    polygon([
        [root_r * cos(root_half_angle), root_r * sin(root_half_angle)],
        [outer_r * cos(tip_half_angle), outer_r * sin(tip_half_angle)],
        [outer_r * cos(-tip_half_angle), outer_r * sin(-tip_half_angle)],
        [root_r * cos(-root_half_angle), root_r * sin(-root_half_angle)]
    ]);
}

