    root_r = pitch_r + mod * 1.25;  // Root is outer for internal gear
    tip_r = pitch_r - mod;           // Tip is inner

    circular_pitch = mod * PI;
    space_width = circular_pitch / 2 + 0.2 + clearance;  // Wider space for clearance

